/**
 * A side pane that shows one artifact a turn produced (`design/components/artifact-pane.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/artifact-pane.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  Render,
  SlotOutlet,
  SlotTemplate,
  agentMember,
  cell,
  derived,
  elementRef,
  focusAfterRemoval,
  isTemplate,
  mountEffect,
  uniqueId,
  useMember,
  watchEffect,
  type Emitted,
  type IconProps,
  type NodeTemplate,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/artifact-pane.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import { SegmentedControl, type SegmentedControlProps } from '../controls/SegmentedControl'
import { Spinner, type SpinnerProps } from '../structure/Spinner'

export type ArtifactKind = 'code' | 'document' | 'data' | 'preview'

export interface ArtifactView {
  id: string
  label: string
  content: NodeTemplate | string
}

/** A side pane that shows one artifact a turn produced: the inputs it takes, by the React member's prop names. */
export interface ArtifactPaneProps {
  /**
   * The close button's accessible name (generic default `Close`), which localized hosts replace.
   */
  closeLabel?: string
  defaultView?: string
  /**
   * The artifact's kind, which picks the mark (the tier's `artifact` glyph when absent).
   */
  kind?: 'code' | 'document' | 'data' | 'preview'
  /**
   * One preformatted line under the title, such as "TypeScript · 142 lines".
   */
  meta?: string
  /**
   * Whether the artifact is still being written, which shows a spinner and sets `aria-busy`.
   */
  streaming?: boolean
  /**
   * The artifact's name, used as the pane's heading and accessible name.
   */
  title: string
  view?: string
  /**
   * The artifact's views (code, preview). Two or more draw a switch, and a single view is drawn
   * with no switch. When `views` is absent or empty, `children` is the body.
   */
  views?: ArtifactView[]
  /**
   * The switch's accessible name (generic default `View`).
   */
  viewsLabel?: string
}

/** A side pane that shows one artifact a turn produced. */
@Component({
  selector: 'pm-artifact-pane',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Render, SlotOutlet, SlotTemplate, Button, Icon, SegmentedControl, Spinner],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<section
[attr.class]="e1()"
[attr.aria-labelledby]="e2()"
[attr.data-kind]="e3()"
[attr.data-state]="e4()"
[attr.aria-busy]="e5()"
data-member="artifact-pane"
[pmRef]="pane"
><header
[attr.class]="e6()"
><span
[attr.class]="e7()"
>@if (e8()) {<pm-spinner
size="sm"
[label]="e9()"
></pm-spinner>} @else {<pm-icon
[name]="e10()"
size="sm"
></pm-icon>}</span>
<div
[attr.class]="e11()"
><h2
[attr.class]="e12()"
[attr.id]="e2()"
>{{ e13() }}</h2>
@if (e14()) {<p
[attr.class]="e15()"
>{{ e16() }}</p>}</div>
@if (e17()) {<div
[attr.class]="e18()"
[pmRef]="switcher"
><pm-segmented-control
size="sm"
[label]="e19()"
[options]="e20()"
[value]="e21()"
(change)="h1($event)"
></pm-segmented-control></div>}
@if (e22()) {<div
[attr.class]="e23()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" /></div>}
@if (e24()) {<div
[attr.class]="e25()"
[pmRef]="closer"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e26()"
icon="close"
[label]="e27()"
(click)="h2()"
></pm-button></div>}</header>
<div
[attr.class]="e28()"
[attr.data-view]="e29()"
[attr.tabindex]="e30()"
[attr.role]="e31()"
[attr.aria-labelledby]="e32()"
[pmRef]="body"
><div
[attr.class]="e33()"
>@if (e34()) {<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" />} @else if (e35()) {{{ e36() }}} @else {@if (template(e37())) {<ng-container [pmRender]="e37()" />} @else {{{ e37() }}}}</div></div></section>`,
})
export class ArtifactPane {
  /**
   * The close button's accessible name (generic default `Close`), which localized hosts replace.
   */
  readonly closeLabel = input<
    Exclude<ArtifactPaneProps['closeLabel'], undefined>,
    ArtifactPaneProps['closeLabel']
  >('Close', {
    transform: (value: ArtifactPaneProps['closeLabel']) => (value === undefined ? 'Close' : value),
  })
  readonly defaultView = input<ArtifactPaneProps['defaultView']>(undefined)
  /**
   * The artifact's kind, which picks the mark (the tier's `artifact` glyph when absent).
   */
  readonly kind = input<ArtifactPaneProps['kind']>(undefined)
  /**
   * One preformatted line under the title, such as "TypeScript · 142 lines".
   */
  readonly meta = input<ArtifactPaneProps['meta']>(undefined)
  /**
   * Whether the artifact is still being written, which shows a spinner and sets `aria-busy`.
   */
  readonly streaming = input<
    Exclude<ArtifactPaneProps['streaming'], undefined>,
    ArtifactPaneProps['streaming']
  >(false, {
    transform: (value: ArtifactPaneProps['streaming']) => (value === undefined ? false : value),
  })
  /**
   * The artifact's name, used as the pane's heading and accessible name.
   */
  readonly title = input.required<ArtifactPaneProps['title']>()
  readonly view = input<ArtifactPaneProps['view']>(undefined)
  /**
   * The artifact's views (code, preview). Two or more draw a switch, and a single view is drawn
   * with no switch. When `views` is absent or empty, `children` is the body.
   */
  readonly views = input<ArtifactPaneProps['views']>(undefined)
  /**
   * The switch's accessible name (generic default `View`).
   */
  readonly viewsLabel = input<
    Exclude<ArtifactPaneProps['viewsLabel'], undefined>,
    ArtifactPaneProps['viewsLabel']
  >('View', {
    transform: (value: ArtifactPaneProps['viewsLabel']) => (value === undefined ? 'View' : value),
  })
  /**
   * Shows the close button when supplied, and the app decides whether the pane stays mounted.
   */
  readonly onClose = output<void>({ alias: 'close' })
  readonly onViewChange = output<string>({ alias: 'viewChange' })
  protected readonly $ = useMember({
    events: ['close', 'viewChange'],
    props: {
      closeLabel: () => this.closeLabel(),
      defaultView: () => this.defaultView(),
      kind: () => this.kind(),
      meta: () => this.meta(),
      streaming: () => this.streaming(),
      title: () => this.title(),
      view: () => this.view(),
      views: () => this.views(),
      viewsLabel: () => this.viewsLabel(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly overflowing = cell(() => false)
  protected readonly mirror = cell(() => this.$p.defaultView ?? this.$p.views?.[0]?.id)
  protected readonly body = elementRef<HTMLElement>()
  protected readonly closer = elementRef<HTMLElement>()
  protected readonly pane = elementRef<HTMLElement>()
  protected readonly switcher = elementRef<HTMLElement>()
  protected readonly titleId = derived(() => `${this.uid}-title`)
  protected readonly current = derived(() => this.$p.view ?? this.mirror.value)
  protected readonly switching = derived(
    () => this.$p.views !== undefined && this.$p.views.length > 1,
  )
  protected readonly shown = derived(() =>
    this.$p.views === undefined
      ? undefined
      : (this.$p.views.find((entry) => entry.id === this.current.value) ?? this.$p.views[0]),
  )
  protected readonly mark = derived(() =>
    this.$p.kind === undefined
      ? 'artifact'
      : ({ code: 'terminal', document: 'document', data: 'table', preview: 'browser' } as const)[
          this.$p.kind
        ],
  )
  protected readonly choices = derived(() =>
    (this.$p.views ?? []).map((entry) => ({ value: entry.id, label: entry.label })),
  )
  protected readonly template = isTemplate
  private release1: (() => void) | undefined
  private release2: (() => void) | undefined
  private release3: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    watchEffect(
      () => this.pane.value,
      () => this.effect1(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    watchEffect(
      () => this.shown.value?.id,
      () => this.effect2(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return styles.pane
  }

  protected e2() {
    return this.titleId.value
  }

  protected e3() {
    return this.$p.kind
  }

  protected e4() {
    return this.$p.streaming ? 'streaming' : undefined
  }

  protected e5() {
    return this.$p.streaming ? true : undefined
  }

  protected e6() {
    return styles.header
  }

  protected e7() {
    return styles.mark
  }

  protected e8() {
    return this.$p.streaming
  }

  protected e9(): SpinnerProps['label'] {
    if (!this.$p.streaming) return undefined as never
    return `${this.$p.title}: still being written`
  }

  protected e10(): IconProps['name'] {
    if (this.$p.streaming) return undefined as never
    return this.mark.value
  }

  protected e11() {
    return styles.heading
  }

  protected e12() {
    return styles.title
  }

  protected e13() {
    return this.$p.title
  }

  protected e14() {
    return this.$p.meta !== undefined
  }

  protected e15() {
    if (!(this.$p.meta !== undefined)) return undefined as never
    return styles.meta
  }

  protected e16() {
    if (!(this.$p.meta !== undefined)) return undefined as never
    return this.$p.meta
  }

  protected e17() {
    return this.switching.value
  }

  protected e18() {
    if (!this.switching.value) return undefined as never
    return styles.views
  }

  protected e19(): SegmentedControlProps['label'] {
    if (!this.switching.value) return undefined as never
    return this.$p.viewsLabel
  }

  protected e20(): SegmentedControlProps['options'] {
    if (!this.switching.value) return undefined as never
    return this.choices.value
  }

  protected e21(): SegmentedControlProps['value'] {
    if (!this.switching.value) return undefined as never
    return this.current.value
  }

  protected h1($event: Emitted<SegmentedControl['onChange']>): void {
    if (!this.switching.value) return
    void ((this.mirror.value = $event), this.$.emit(this.onViewChange, 'onViewChange', $event))
  }

  protected e22() {
    return this.$.filled('actions')
  }

  protected e23() {
    if (!this.$.filled('actions')) return undefined as never
    return styles.actions
  }

  protected e24() {
    return this.$.listening(this.onClose, 'onClose')
  }

  protected e25() {
    if (!this.$.listening(this.onClose, 'onClose')) return undefined as never
    return styles.close
  }

  protected e26(): ButtonProps['iconOnly'] {
    if (!this.$.listening(this.onClose, 'onClose')) return undefined as never
    return true
  }

  protected e27(): ButtonProps['label'] {
    if (!this.$.listening(this.onClose, 'onClose')) return undefined as never
    return this.$p.closeLabel
  }

  protected h2(): void {
    if (!this.$.listening(this.onClose, 'onClose')) return
    this.$.emit(this.onClose, 'onClose')
  }

  protected e28() {
    return styles.body
  }

  protected e29() {
    return this.shown.value?.id
  }

  protected e30() {
    return this.overflowing.value ? 0 : undefined
  }

  protected e31() {
    return this.overflowing.value ? 'group' : undefined
  }

  protected e32() {
    return this.overflowing.value ? this.titleId.value : undefined
  }

  protected e33() {
    return styles.content
  }

  protected e34() {
    return this.shown.value === undefined
  }

  protected e35() {
    if (this.shown.value === undefined) return undefined as never
    return typeof this.shown.value.content === 'string'
  }

  protected e36() {
    if (this.shown.value === undefined) return undefined as never
    if (!(typeof this.shown.value.content === 'string')) return undefined as never
    return this.shown.value.content
  }

  protected e37() {
    if (this.shown.value === undefined) return undefined as never
    if (typeof this.shown.value.content === 'string') return undefined as never
    return this.shown.value.content
  }

  private effect1(): void {
    this.release1?.()
    const ran = focusAfterRemoval(this.pane.value)
    this.release1 = () => {
      ran()
    }
  }

  private effect2(): void {
    this.release2?.()
    const run = () => {
      this.overflowing.value =
        this.body.value !== null && this.body.value.scrollHeight > this.body.value.clientHeight
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.body.value, this.body.value?.firstElementChild])
      if (element) resize?.observe(element)
    this.release2 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect3(): void {
    this.release3?.()
    const ran = agentMember({
      member: 'ArtifactPane',
      element: () => this.pane.value,
      state: () => ({
        view: this.shown.value?.id ?? null,
        views: (this.$p.views ?? []).map((entry) => ({ id: entry.id, label: entry.label })),
        streaming: this.$p.streaming,
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) =>
            value !== this.shown.value?.id &&
            ((this.mirror.value = value), this.$.emit(this.onViewChange, 'onViewChange', value)),
        },
        close: () =>
          (() => {
            if (!this.$.listening(this.onClose, 'onClose'))
              throw new Error('The pane has no close control.')
            this.$.emit(this.onClose, 'onClose')
          })(),
      },
      withholds: () => [this.switcher.value, this.closer.value],
    })
    this.release3 = () => {
      ran()
    }
  }
}
